var c7 = new Seat('C', 7);

Check.True(typeof(Seat).IsValueType, "Seat is a record struct, so a value type");
Check.Equal(c7.Row, 'C', "the row of a seat");
Check.Equal(c7.Number, 7, "the number of a seat");

// Value equality, generated by the compiler.
Check.True(c7 == new Seat('C', 7), "== on two seats with the same values");
Check.True(!(c7 != new Seat('C', 7)), "!= on two seats with the same values");
Check.True(c7 != new Seat('C', 8), "!= on two seats with different numbers");
Check.True(c7 != new Seat('D', 7), "!= on two seats in different rows");
Check.True(c7.Equals(new Seat('C', 7)), "Equals on two seats with the same values");
Check.True(c7.GetHashCode() == new Seat('C', 7).GetHashCode(), "the hash codes of two equal seats");

var taken = new HashSet<Seat> { c7, new Seat('A', 1) };
Check.True(taken.Contains(new Seat('C', 7)), "a HashSet finds a seat by its values");
Check.True(!taken.Add(new Seat('A', 1)), "a HashSet refuses a second equal seat");
var holders = new Dictionary<Seat, string> { [new Seat('F', 12)] = "Dee" };
Check.Equal(holders[new Seat('F', 12)], "Dee", "a dictionary finds a seat key by its values");

// The generated ToString lists the properties in order.
Check.Equal(new Seat('A', 1).ToString(), "Seat { Row = A, Number = 1 }", "the text of seat A1");
Check.Equal($"{new Seat('M', 24)}", "Seat { Row = M, Number = 24 }", "a seat in an interpolated string");
